<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Enums\UserRole;
use App\Models\{User,Event,EventRegistration,AttendanceVerification,EventCreatorAccess,EventCategory};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class MonitoringController extends Controller {
 private function admin(): User {$user=request()->user();abort_unless($user->role===UserRole::Admin,403);return $user;}
 public function dashboard(){ $user=$this->admin();$base=Event::where(fn($q)=>$q->where('organizer_program_id',$user->study_program_id)->orWhere('creator_id',$user->id));$ids=(clone $base)->pluck('id');$stats=['events'=>(clone $base)->where('status','published')->count(),'registrations'=>EventRegistration::whereIn('event_id',$ids)->where('status','pending')->count(),'verifications'=>AttendanceVerification::whereHas('registration',fn($q)=>$q->whereIn('event_id',$ids))->where('verification_status','pending')->count(),'students'=>User::where('study_program_id',$user->study_program_id)->where('role','mahasiswa')->count()];return view('admin.dashboard',compact('stats'));}
 public function pending(){ $user=$this->admin();$ids=Event::where(fn($q)=>$q->where('organizer_program_id',$user->study_program_id)->orWhere('creator_id',$user->id))->pluck('id');return view('admin.pending',['registrations'=>EventRegistration::with(['event','user'])->whereIn('event_id',$ids)->where('status','pending')->latest()->paginate(10),'verifications'=>AttendanceVerification::with(['registration.event','registration.user'])->whereHas('registration',fn($q)=>$q->whereIn('event_id',$ids))->where('verification_status','pending')->latest()->paginate(10,'*','verifications')]);}
 public function students(Request $request){$user=$this->admin();$students=User::where('role','mahasiswa')->where('study_program_id',$user->study_program_id)->with('studyProgram')->withSum('rewards as jam_total','jam_plus')->withSum('rewards as soft_total','soft_skill_points')->when($request->filled('angkatan'),fn($q)=>$q->where('angkatan',$request->angkatan))->orderBy('name')->paginate(15)->withQueryString();return view('admin.students',compact('students'));}
 public function access(){ $user=$this->admin();return view('admin.access',['accesses'=>EventCreatorAccess::with('user')->where('study_program_id',$user->study_program_id)->latest()->paginate(12),'students'=>User::where('role','mahasiswa')->where('study_program_id',$user->study_program_id)->orderBy('name')->get()]); }
 public function grant(Request $request){$admin=$this->admin();$data=$request->validate(['user_id'=>['required','exists:users,id']]);$student=User::whereKey($data['user_id'])->where('role','mahasiswa')->where('study_program_id',$admin->study_program_id)->firstOrFail();EventCreatorAccess::updateOrCreate(['user_id'=>$student->id,'study_program_id'=>$admin->study_program_id],['granted_by'=>$admin->id,'granted_at'=>now(),'revoked_at'=>null,'is_active'=>true]);return back()->with('success','Akses pembuat acara diaktifkan.');}
 public function revoke(EventCreatorAccess $access){$admin=$this->admin();abort_unless($access->study_program_id===$admin->study_program_id,403);$access->update(['is_active'=>false,'revoked_at'=>now()]);return back()->with('success','Akses pembuat acara dicabut.');}
 public function categories(){ $this->admin();return view('admin.categories',['categories'=>EventCategory::orderBy('name')->get()]);}
 public function saveCategory(Request $request){$this->admin();$data=$request->validate(['name'=>['required','string','max:100'],'description'=>['nullable','string']]);EventCategory::create($data);return back()->with('success','Kategori berhasil ditambahkan.');}
 public function updateCategory(Request $request,EventCategory $category){$this->admin();$data=$request->validate(['name'=>['required','string','max:100'],'description'=>['nullable','string']]);$category->update($data);return back()->with('success','Kategori diperbarui.');}
 public function deleteCategory(EventCategory $category){$this->admin();abort_if($category->events()->exists(),422,'Kategori masih digunakan event.');$category->delete();return back()->with('success','Kategori dihapus.');}
 public function import(Request $request){$user=$this->admin();$request->validate(['csv'=>['required','file','mimes:csv,txt','max:5120']]);$handle=fopen($request->file('csv')->getRealPath(),'r');$header=array_map(fn($v)=>strtolower(trim(preg_replace('/^\xEF\xBB\xBF/','',$v))),fgetcsv($handle)?:[]);$expected=['nim','nama','email','angkatan'];if(array_diff($expected,$header)){fclose($handle);return back()->withErrors(['csv'=>'Header CSV wajib: nim,nama,email,angkatan']);}$count=0;
  DB::transaction(function()use($handle,$header,$user,&$count){while(($row=fgetcsv($handle))!==false){if(count($row)!==count($header))continue;$record=array_combine($header,$row);if(!filter_var($record['email'],FILTER_VALIDATE_EMAIL) || !$record['nim'] || !$record['nama'] || !preg_match('/^(19|20)\d{2}$/',$record['angkatan']))continue;User::firstOrCreate(['email'=>$record['email']],['study_program_id'=>$user->study_program_id,'name'=>$record['nama'],'student_number'=>$record['nim'],'angkatan'=>(int)$record['angkatan'],'role'=>UserRole::Mahasiswa,'password'=>$record['nim'],'is_active'=>true]);$count++;}});fclose($handle);return back()->with('success',"CSV diproses: {$count} baris valid."); }
}
